levels.solution:
library(shiny)

ui <- fluidPage(
  textInput("n", "Your name", "world"),
  textOutput("greeting")
)

server <- function(input, output, session) {
  output$greeting <- renderText({
    paste0("Hello, ", input$n, "!")
  })
}

shinyApp(ui, server)

