levels.solution:
server <- function(input, output, session) {
  output$out <- renderText({
    paste("x² =", input$x * input$x)
  })
}

levels.starterCode:
library(shiny)

ui <- fluidPage(
  numericInput("x", "X", 1),
  textOutput("out"),
  textOutput("out2")
)

server <- function(input, output, session) {
  # add reactive y = x * 2
  output$out <- renderText({
    paste("y =", input$x * 2)
  })
  output$out2 <- renderText({
    paste("y again =", input$x * 2)
  })
}

shinyApp(ui, server)

levels.solution:
server <- function(input, output, session) {
  y <- reactive({
    input$x * 2
  })
  output$out <- renderText({
    paste("y =", y())
  })
  output$out2 <- renderText({
    paste("y again =", y())
  })
}

levels.starterCode:
library(shiny)

ui <- fluidPage(
  sliderInput("x", "X", 0, 10, 1),
  actionButton("go", "Commit"),
  textOutput("out")
)

server <- function(input, output, session) {
  # out should only update when go is pressed
  output$out <- renderText({
    paste("x =", input$x)
  })
}

shinyApp(ui, server)

levels.solution:
server <- function(input, output, session) {
  snap <- eventReactive(input$go, {
    input$x
  })
  output$out <- renderText({
    paste("x =", snap())
  })
}

